import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Existing NPC producers plus frozen physical-area member consumers. */
public final class NpcWeaponActionMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",H=P+"NativeNpcWeaponBreakActions";
 static final Map<String,String[]> SPECS=Map.of("serverClassicWorldMonsterAttack",new String[]{"nativeNpcWeaponMonsterBody","normal"},"serverClassicWorldMonsterCompanionAttack",new String[]{"nativeNpcWeaponCompanionBody","companion"},"serverClassicWorldDspyFollowerAttack",new String[]{"nativeNpcWeaponDspyBody","dspy"},"serverClassicWorldMonsterPhysicalSkillAttack",new String[]{"nativeNpcWeaponPhysicalBody","run"});
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static void patch(ClassNode c){int count=0;for(var m:new ArrayList<>(c.methods))if(SPECS.containsKey(m.name)){var names=SPECS.get(m.name);if(c.methods.stream().anyMatch(x->x.name.equals(names[0])))throw new AssertionError("duplicate body");String entry=m.name;var wrapper=new MethodNode(m.access,entry,m.desc,m.signature,m.exceptions.toArray(String[]::new));wrapper.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));wrapper.instructions.add(new VarInsnNode(Opcodes.ALOAD,1));if(m.desc.contains(";J)"))wrapper.instructions.add(new VarInsnNode(Opcodes.LLOAD,2));wrapper.instructions.add(new MethodInsnNode(Opcodes.INVOKESTATIC,entry.equals("serverClassicWorldMonsterPhysicalSkillAttack")?P+"NativeNpcWeaponBreakAreaActions":H,names[1],"(L"+PC+";"+m.desc.substring(1),false));wrapper.instructions.add(new InsnNode(Opcodes.RETURN));m.name=names[0];c.methods.add(wrapper);count++;}if(count!=4)throw new AssertionError("NPC producer count "+count);
  int members=0;for(var m:c.methods)if(Set.of("nativeNpcWeaponPhysicalBody","classicWorldMonsterPhysicalTarget","classicWorldMonsterPhysicalAreaTargets").contains(m.name))for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(PC)&&call.name.equals("classicWorldMembers")&&call.desc.equals("(I)Ljava/util/List;")){call.setOpcode(Opcodes.INVOKESTATIC);call.owner=P+"NativeNpcWeaponBreakAreaActions";call.name="members";call.desc="(L"+PC+";I)Ljava/util/List;";members++;}if(members!=2)throw new AssertionError("physical target/area/viewer membership count "+members);
  int pets=0;for(var m:c.methods)if(m.name.equals("classicWorldMonsterPhysicalTarget"))for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(PC)&&call.name.equals("ownedCompanion")){call.setOpcode(Opcodes.INVOKESTATIC);call.owner=P+"NativeNpcWeaponBreakAreaActions";call.name="companion";call.desc="(L"+PC+";J)L"+P+"BattleCompanion;";pets++;}if(pets!=1)throw new AssertionError("physical pet target count "+pets);
 }
 public static void main(String[]args)throws Exception{try(var old=new JarFile(args[1])){for(String name:List.of(PC)){var c=read(old,name);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(name+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var next=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(next,name))))throw new AssertionError("exact NPC producer/context regeneration");}}}System.out.println("PASS four NPC producer boundaries, two physical member ports and companion identity; no fields, new schedulers or registries");}
}
